import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`team lead: set up custom pipeline stages like New, Contacted, Proposal, Won, and Lost`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after the team lead saves a new set of stages, every team member sees the updated stage columns within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();

    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Team lead (node 0) opens the Manage Pipeline Stages modal
      await pageA.getByRole('button', { name: /Stages/i }).click();
      await expect(pageA.getByText('Manage Pipeline Stages')).toBeVisible({ timeout: 5_000 });

      // Add a unique custom stage so we have something distinctive to assert on
      await pageA.getByPlaceholder('New stage name…').fill('E2E-Custom-Stage');
      await pageA.getByRole('button', { name: '+ Add' }).click();

      // Verify the stage was added to the list in the modal
      await expect(pageA.getByText('E2E-Custom-Stage')).toBeVisible({ timeout: 3_000 });

      // Save the updated stage configuration
      await pageA.getByRole('button', { name: 'Save Stages' }).click();

      // Team lead sees the new stage column on the kanban board
      await expect(pageA.getByText('E2E-Custom-Stage')).toBeVisible({ timeout: 5_000 });

      // Every team member (node 1) sees the updated stage column within 5 s
      await expect(pageB.getByText('E2E-Custom-Stage')).toBeVisible({ timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });
});
